<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Accessor\SnippetVersionContentHtmlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SnippetVersionContentHtmlAccessor trait.
 *
 * Covers null default, string/VO assignment via withContentHtml,
 * getContentHtml/contentHtml accessors, and isContentHtmlChanged with/without original.
 */
class SnippetVersionContentHtmlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withContentHtml creates a new instance with the ContentHtml set
     * from a string value, and getContentHtml returns the primitive string.
     */
    public function testWithContentHtmlFromString(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionContentHtmlAccessorUnitTest();

        // Act
        $result = $holder->withContentHtml('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getContentHtml());
    }
    /**
     * Asserts that withcontentHtml has access to the value object
     * from a string value, and getContentHtml returns the primitive string.
     */
    public function testWithContentHtmlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionContentHtmlAccessorUnitTest();

        // Act
        $result = $holder->withContentHtml('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->contentHtml()->value());
    }
    public function testChangedContentHtml(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionContentHtmlAccessorUnitTest()->withContentHtml('one');
        $original = $holder->withContentHtml('one');
        $same = $holder->withContentHtml('one');
        $modified = $holder->withContentHtml('other');

        // Act
        $withSame = $original->isContentHtmlChanged($same);
        $withDiferent = $original->isContentHtmlChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSnippetVersionContentHtmlAccessorUnitTest
{
    use SnippetVersionContentHtmlAccessor;
}
